import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"Настройка журнала","description":"","frontmatter":{},"headers":[],"relativePath":"ru/config/log.md","filePath":"ru/config/log.md","lastUpdated":1786051418000}`),a={name:`ru/config/log.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="настроика-журнала" tabindex="-1">Настройка журнала <a class="header-anchor" href="#настроика-журнала" aria-label="Permalink to “Настройка журнала”">​</a></h1><p>Настройка журнала управляет тем, как Xray выводит журналы.</p><p>Xray имеет два типа журналов: журнал доступа и журнал ошибок.<br> Вы можете настроить способ вывода каждого типа журнала отдельно.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Настройки логирования применяются не сразу. Поэтому в процессе запуска вы можете увидеть записи от несконфигурированного логгера. Например, могут появиться сообщения уровня <code>&quot;info&quot;</code>, даже если вы установили уровень логирования <code>&quot;warning&quot;</code>.</p></div><h2 id="logobject" tabindex="-1">LogObject <a class="header-anchor" href="#logobject" aria-label="Permalink to “LogObject”">​</a></h2><p>LogObject соответствует полю <code>log</code> в конфигурационном файле.</p><div class="language-json line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">{</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;log&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: {</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">    &quot;access&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;путь/к/файлу&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">    &quot;error&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;путь/к/файлу&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">    &quot;loglevel&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;warning&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">    &quot;dnsLog&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#569CD6;--shiki-light:#0000FF;">false</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">    &quot;maskAddress&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">  }</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><blockquote><p><code>access</code>: string</p></blockquote><p>Путь к файлу журнала доступа.<br> Значение должно быть допустимым путем к файлу, например <code>&quot;/var/log/Xray/access.log&quot;</code> (Linux) или <code>&quot;C:\\\\Temp\\\\Xray\\\\_access.log&quot;</code> (Windows).<br> Если этот параметр не указан или имеет пустое значение, журнал выводится в stdout.</p><ul><li>Специальное значение <code>none</code> отключает журнал доступа.</li></ul><blockquote><p><code>error</code>: string</p></blockquote><p>Путь к файлу журнала ошибок.<br> Значение должно быть допустимым путем к файлу, например <code>&quot;/var/log/Xray/error.log&quot;</code> (Linux) или <code>&quot;C:\\\\Temp\\\\Xray\\\\_error.log&quot;</code> (Windows).<br> Если этот параметр не указан или имеет пустое значение, журнал выводится в stdout.</p><ul><li>Специальное значение <code>none</code> отключает журнал ошибок.</li></ul><blockquote><p><code>loglevel</code>: &quot;debug&quot; | &quot;info&quot; | &quot;warning&quot; | &quot;error&quot; | &quot;none&quot;</p></blockquote><p>Уровень логирования для журнала ошибок, указывающий, какая информация должна быть записана. Значение по умолчанию — <code>&quot;warning&quot;</code>. Обратите внимание, что этот параметр применяется только к журналу ошибок. Он не влияет на журнал доступа (за исключением значения <code>&quot;none&quot;</code>). Журнал доступа не имеет уровней логирования.</p><ul><li><code>&quot;debug&quot;</code>: информация, используемая при отладке программы.<br> Включает всю информацию уровня <code>&quot;info&quot;</code>.</li><li><code>&quot;info&quot;</code>: информация о состоянии во время выполнения и т.д., не влияющая на нормальную работу.<br> Включает всю информацию уровня <code>&quot;warning&quot;</code>.</li><li><code>&quot;warning&quot;</code>: информация, выводимая при возникновении проблем, не влияющих на нормальную работу, но которые могут повлиять на работу пользователя.<br> Включает всю информацию уровня <code>&quot;error&quot;</code>.</li><li><code>&quot;error&quot;</code>: Xray столкнулся с проблемой, которая не позволяет ему работать нормально, и ее необходимо немедленно решить.</li><li><code>&quot;none&quot;</code>: не записывать ничего.</li></ul><blockquote><p><code>dnsLog</code>: bool</p></blockquote><p>Записывать DNS-запросы, сделанные встроенными DNS-клиентами, в журнал доступа. Пример записи в журнале: DOH//doh.server got answer: domain.com -&gt; [ip1, ip2] 2.333ms.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><ol><li><p>Xray не выполняет все DNS-запросы через свои встроенные клиенты. Поэтому включение этой опции не означает, что все DNS-запросы, выполняемые Xray, будут записаны в журнал.</p></li><li><p>DNS-запросы, сделанные встроенными DNS-клиентами, также записываются в журнал ошибок (с уровнем &quot;Info&quot;) даже если эта опция отключена.</p></li><li><p>Запросы клиента FakeDNS никогда не записываются в журнал доступа.</p></li></ol></div><blockquote><p><code>maskAddress</code>: &quot;quarter&quot; | &quot;half&quot; | &quot;full&quot;</p></blockquote><p>Маскировка IP-адресов. При включении автоматически заменяет IP-адреса, встречающиеся в логах, для защиты конфиденциальности при совместном использовании логов. По умолчанию не включено.</p><p>В настоящее время доступны следующие уровни маскировки: <code>quarter</code>, <code>half</code>, <code>full</code>. Соответствующие форматы маскировки:</p><ul><li>ipv4 <code>1.2.*.*</code> <code>1.*.*.*</code> <code>[Masked IPv4]</code></li><li>ipv6 <code>1234:5678::/32</code> <code>1234::/16</code> <code>[Masked IPv6]</code></li></ul><p>При более специфических требованиях можно использовать пользовательский формат, например <code>/16+/32</code>. Формат задает количество бит, которые остаются немаскированными; первое число относится к IPv4, второе — к IPv6, причем значение для IPv4 должно делиться на 8. <code>/32</code> или <code>/128</code> означает полное отсутствие маскировки, а <code>/0</code> приводит к отображению <code>[Masked IPv4/IPv6]</code>.</p>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};